files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-block-size: 100dvb;
  margin: 0;
  padding: 2em;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #000;
}

h1 {
  margin: 0;
  color: #fff;
  font-size: 3em;
  text-align: center;
  text-transform: uppercase;
  text-wrap: balance;
}

.martini {
  inline-size: 40%;
  filter: drop-shadow(var(--x-shadow, 0) var(--y-shadow, 0) 2px #fd24af);
}

@media (width <= 720px) {
  .martini {
    inline-size: 90%;
  }
}
